const from = "2026-07-16T11:39:53Z";
const until = "2026-07-16T11:46:56Z";
const teamId = "REDACTED";
const agentId = "REDACTED";
const [prodRuns, previewRuns] = await Promise.all([
  tools.mcp__codex_apps__vercel_list_agent_runs({projectId:agentId,teamId,environment:"production",from,to:until,page:1,pageSize:100}),
  tools.mcp__codex_apps__vercel_list_agent_runs({projectId:agentId,teamId,environment:"preview",from,to:until,page:1,pageSize:100})
]);
const summarize = (r) => {
  const raw = r.content?.filter((c) => c.type === "text").map((c) => c.text).join("\n") ?? "";
  const data = JSON.parse(raw);
  return {
    isError: Boolean(r.isError),
    runCount: data.summary?.runs ?? null,
    total: data.pageInfo?.total ?? null,
    completed: data.summary?.completed ?? null,
    failed: data.summary?.failed ?? null,
    cancelled: data.summary?.cancelled ?? null,
    runIds: Array.isArray(data.runs) ? data.runs.map((run) => run.id ?? run.runId).filter(Boolean) : [],
    runMetadata: Array.isArray(data.runs) ? data.runs.map((run) => ({
      status: run.status ?? null,
      createdAt: run.createdAt ?? run.created_at ?? null,
      updatedAt: run.updatedAt ?? run.updated_at ?? null
    })) : []
  };
};
text(JSON.stringify({from,until,production:summarize(prodRuns),preview:summarize(previewRuns)}));

const r = await tools.exec_command({"cmd":"set -u
set +o xtrace
unset HISTFILE
set +o history 2>/dev/null || true
/bin/sh -c '
  set -a
  . .local/secrets/executor-production.env
  set +a
  case "$BUNDJIL_EXECUTOR_MCP_URL" in
    */toolkits/bundjil-production\?*) exit 10 ;;
    */toolkits/bundjil-preview\?*) exit 11 ;;
    *) exit 12 ;;
  esac
'
rc=$?
case "$rc" in
  10) printf 'environment=local-production-file toolkit=bundjil-production\n' ;;
  11) printf 'environment=local-production-file toolkit=bundjil-preview\n' ;;
  12) printf 'environment=local-production-file toolkit=unknown\n' ;;
  *) printf 'environment=local-production-file toolkit=unreadable\n' ;;
esac
","workdir":"/Users/cooper/Projects/bundjil","yield_time_ms":10000,"max_output_tokens":1000});
text(r.output);

const r = await tools.exec_command({"cmd":"set +o xtrace
unset HISTFILE
set +o history 2>/dev/null || true
/bin/sh -c '
  set -a
  . .local/secrets/executor-production.env
  set +a
  case "$BUNDJIL_EXECUTOR_MCP_URL" in
    */toolkits/bundjil-production\?*) exit 10 ;;
