const classify = (value) => value.includes("/toolkits/bundjil-production?") ? "bundjil-production" : value.includes("/toolkits/bundjil-preview?") ? "bundjil-preview" : "unknown";
const fingerprint = async (value) => {
  const bytes = new TextEncoder().encode(value);
